client/src/pages/ProfilePage.tsx.content:
import { useState } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { Button } from "@/components/ui/button";
import { Card } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Switch } from "@/components/ui/switch";
import { useToast } from "@/hooks/use-toast";
import { useLocation } from "wouter";
import type { User } from "@shared/schema";

export default function ProfilePage() {
  const { toast } = useToast();
  const [, setLocation] = useLocation();
  const { data: profile } = useQuery<User>({ queryKey: ["/api/user/profile"] });

  const [fullName, setFullName] = useState("");
  const [phone, setPhone] = useState("");
  const [organization, setOrganization] = useState("");
  const [currentPassword, setCurrentPassword] = useState("");
  const [newPassword, setNewPassword] = useState("");
  const [confirmPassword, setConfirmPassword] = useState("");
  const [twoFactorEnabled, setTwoFactorEnabled] = useState(false);

  const updateMutation = useMutation({
    mutationFn: async (updates: any) => {
      return apiRequest("/api/user/profile", {
        method: "PUT",
        body: JSON.stringify(updates),
      });
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/user/profile"] });
      toast({ 
        title: "✓ Profile updated successfully!",
        className: "bg-emerald-500 text-white border-0"
      });
      setFullName("");
      setPhone("");
      setOrganization("");
      setCurrentPassword("");
      setNewPassword("");
      setConfirmPassword("");
    },
    onError: (error: any) => {
      toast({ title: "Error", description: error.message, variant: "destructive" });
    },
  });

  const handlePersonalInfoSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const updates: any = {};
    if (fullName) updates.fullName = fullName;
    if (Object.keys(updates).length > 0) {
      updateMutation.mutate(updates);
    }
  };

  const handlePasswordChange = (e: React.FormEvent) => {
    e.preventDefault();
    if (newPassword !== confirmPassword) {
      toast({ title: "Error", description: "Passwords do not match", variant: "destructive" });
      return;
    }
    if (newPassword) {
      updateMutation.mutate({ password: newPassword });
    }
  };

  const handleLogout = () => {
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    setLocation("/");
  };

  return (
    <div className="max-w-6xl mx-auto">
      <Card className="bg-[#2a3749] border-[#3a4759] p-8 mb-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center gap-6">
            <div className="w-24 h-24 rounded-full bg-gradient-to-br from-emerald-400 to-teal-600 flex items-center justify-center">
              <span className="text-white font-bold text-3xl">
                {profile?.email?.[0]?.toUpperCase() || "J"}D
              </span>
            </div>
            <div>
              <h2 className="text-2xl font-bold text-white">{profile?.fullName || "John Doe"}</h2>
              <p className="text-gray-400">{profile?.email || "john.doe@agritech.com"}</p>
              <p className="text-sm text-gray-500">
                Member since {profile?.createdAt ? new Date(profile.createdAt).toLocaleDateString('en-US', { month: 'long', year: 'numeric' }) : "March 2024"}
              </p>
            </div>
          </div>
          <Button 
            onClick={handleLogout}
            className="bg-red-500 hover:bg-red-600 text-white"
            data-testid="button-logout"
          >
            Logout
          </Button>
        </div>
      </Card>

      <div className="space-y-6">
        <h1 className="text-2xl font-bold text-white" data-testid="heading-profile">Profile Settings</h1>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
          <Card className="bg-[#2a3749] border-[#3a4759] p-6">
            <h3 className="text-xl font-semibold text-white mb-6">Personal Information</h3>

            <form onSubmit={handlePersonalInfoSubmit} className="space-y-4">
              <div className="space-y-2">
                <Label className="text-gray-300">Full Name</Label>
                <div className="flex gap-2">
                  <Input
                    value={fullName || profile?.fullName || ""}
                    onChange={(e) => setFullName(e.target.value)}
                    className="bg-[#1a2332] border-[#3a4759] text-white"
                    placeholder="John Doe"
                    data-testid="input-fullname"
                  />
                  <Button size="sm" className="bg-emerald-500 hover:bg-emerald-600" data-testid="button-update-name">
                    ✓
                  </Button>
                </div>
              </div>

              <div className="space-y-2">
                <Label className="text-gray-300">Email Address</Label>
                <div className="flex gap-2">
                  <Input
                    value={profile?.email || ""}
                    readOnly
                    className="bg-[#1a2332] border-[#3a4759] text-white"
                    data-testid="text-email"
                  />
                  <Button size="sm" className="bg-yellow-500 hover:bg-yellow-600" data-testid="button-edit-email">
                    ✏️
                  </Button>
                </div>
              </div>

              <div className="space-y-2">
                <Label className="text-gray-300">Phone Number</Label>
                <div className="flex gap-2">
                  <Input
                    value={phone}
                    onChange={(e) => setPhone(e.target.value)}
                    className="bg-[#1a2332] border-[#3a4759] text-white"
                    placeholder="+91 98765 43210"
                    data-testid="input-phone"
                  />
                  <Button size="sm" className="bg-yellow-500 hover:bg-yellow-600" data-testid="button-edit-phone">
                    ✏️
                  </Button>
                </div>
              </div>

              <div className="space-y-2">
                <Label className="text-gray-300">Organization</Label>
                <div className="flex gap-2">
                  <Input
                    value={organization}
                    onChange={(e) => setOrganization(e.target.value)}
                    className="bg-[#1a2332] border-[#3a4759] text-white"
                    placeholder="AgriTech Solutions Pvt Ltd"
                    data-testid="input-organization"
                  />
                  <Button size="sm" className="bg-yellow-500 hover:bg-yellow-600" data-testid="button-edit-org">
                    ✏️
                  </Button>
                </div>
              </div>

              <div className="flex gap-3 pt-4">
                <Button 
                  type="submit"
                  className="bg-emerald-500 hover:bg-emerald-600 text-white"
                  disabled={updateMutation.isPending}
                  data-testid="button-save-changes"
                >
                  Save Changes
                </Button>
                <Button 
                  type="button"
                  variant="outline"
                  className="bg-transparent border-gray-600 text-gray-400 hover:bg-[#1a2332]"
                  data-testid="button-cancel"
                >
                  Cancel
                </Button>
              </div>
            </form>
          </Card>

          <Card className="bg-[#2a3749] border-[#3a4759] p-6">
            <h3 className="text-xl font-semibold text-white mb-6">Security Settings</h3>

            <form onSubmit={handlePasswordChange} className="space-y-4">
              <div className="space-y-2">
                <Label className="text-gray-300">Current Password</Label>
                <div className="flex gap-2">
                  <Input
                    type="password"
                    value={currentPassword}
                    onChange={(e) => setCurrentPassword(e.target.value)}
                    className="bg-[#1a2332] border-[#3a4759] text-white"
                    placeholder="••••••••••••"
                    data-testid="input-current-password"
                  />
                  <Button size="sm" className="bg-red-500 hover:bg-red-600" data-testid="button-change-password">
                    CHANGE
                  </Button>
                </div>
              </div>

              <div className="space-y-2">
                <Label className="text-gray-300">New Password</Label>
                <Input
                  type="password"
                  value={newPassword}
                  onChange={(e) => setNewPassword(e.target.value)}
                  className="bg-[#1a2332] border-[#3a4759] text-white"
                  placeholder="Enter new password"
                  data-testid="input-new-password"
                />
              </div>

              <div className="space-y-2">
                <Label className="text-gray-300">Confirm New Password</Label>
                <Input
                  type="password"
                  value={confirmPassword}
                  onChange={(e) => setConfirmPassword(e.target.value)}
                  className="bg-[#1a2332] border-[#3a4759] text-white"
                  placeholder="Confirm new password"
                  data-testid="input-confirm-password"
                />
              </div>

              <div className="space-y-2 pt-4">
                <Label className="text-gray-300">Two-Factor Authentication</Label>
                <div className="flex items-center justify-between bg-[#1a2332] border border-[#3a4759] rounded-lg p-4">
                  <div className="flex items-center gap-3">
                    <div className="w-2 h-2 rounded-full bg-emerald-400"></div>
                    <span className="text-white">Enabled</span>
                  </div>
                  <div className="flex items-center gap-3">
                    <Switch
                      checked={twoFactorEnabled}
                      onCheckedChange={setTwoFactorEnabled}
                      className="data-[state=checked]:bg-emerald-500"
                      data-testid="switch-2fa"
                    />
                    <Button size="sm" className="bg-yellow-500 hover:bg-yellow-600" data-testid="button-setup-2fa">
                      SETUP
                    </Button>
                  </div>
                </div>
              </div>
            </form>
          </Card>
        </div>
      </div>
    </div>
  );
}

client/src/pages/AdminLogin.tsx.content:
import { useState } from "react";
import { useLocation } from "wouter";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { useToast } from "@/hooks/use-toast";
import { useMutation } from "@tanstack/react-query";
import { apiRequest } from "@/lib/queryClient";
import { Shield, CheckIcon } from "lucide-react";

const adminFeatures = [
  "User Management",
  "Content Moderation",
  "System Analytics",
];

export default function AdminLogin() {
  const [, setLocation] = useLocation();
  const { toast } = useToast();
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const loginMutation = useMutation({
    mutationFn: async (credentials: { email: string; password: string }) => {
      const result = await apiRequest("/api/auth/login", {
        method: "POST",
        body: JSON.stringify(credentials),
      });
      return result;
    },
    onSuccess: (data: any) => {
      if (data.user.role !== "admin") {
        toast({
          title: "Access Denied",
          description: "Admin access required",
          variant: "destructive",
        });
        return;
      }
      localStorage.setItem("token", data.token);
      localStorage.setItem("user", JSON.stringify(data.user));
      toast({
        title: "Success",
        description: "Logged in successfully",
      });
      setLocation("/admin/dashboard");
    },
    onError: (error: any) => {
      toast({
        title: "Error",
        description: error.message || "Login failed",
        variant: "destructive",
      });
    },
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    loginMutation.mutate({ email, password });
  };

  return (
    <div className="relative flex items-center justify-center min-h-screen w-full overflow-hidden bg-[#0a1628]">
      <div className="absolute w-32 h-32 bg-blue-600/20 rounded-full blur-3xl top-10 left-20"></div>
      <div className="absolute w-24 h-24 bg-blue-600/20 rounded-full blur-3xl top-32 right-40"></div>
      <div className="absolute w-40 h-40 bg-blue-600/20 rounded-full blur-3xl bottom-20 left-32"></div>
      <div className="absolute w-28 h-28 bg-blue-600/20 rounded-full blur-3xl bottom-40 right-20"></div>

      <div className="relative z-10 flex items-center justify-center gap-16 w-full max-w-7xl px-8">
        <Card className="w-full max-w-md bg-gradient-to-br from-blue-900/40 to-blue-800/30 border-blue-700/50 backdrop-blur-sm">
          <CardContent className="pt-12 pb-12 px-12">
            <div className="flex flex-col items-center mb-8">
              <div className="relative mb-6">
                <div className="absolute inset-0 bg-blue-500/30 rounded-full blur-2xl"></div>
                <div className="relative w-20 h-20 bg-blue-500 rounded-full flex items-center justify-center">
                  <Shield className="w-10 h-10 text-white" />
                </div>
              </div>
              <h1 className="text-3xl font-bold text-white mb-2">Admin Portal</h1>
              <p className="text-slate-300 text-base">AgriSearch Management</p>
            </div>

            <div className="space-y-4">
              {adminFeatures.map((feature, index) => (
                <div key={index} className="flex items-center gap-3">
                  <div className="flex-shrink-0 w-5 h-5 bg-blue-500 rounded-full flex items-center justify-center">
                    <CheckIcon className="w-3 h-3 text-white" />
                  </div>
                  <span className="text-slate-200 text-sm">{feature}</span>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>

        <Card className="w-full max-w-md bg-white border-gray-200">
          <CardHeader className="text-center pb-6">
            <CardTitle className="text-3xl font-bold text-slate-800">
              Admin Sign In
            </CardTitle>
            <CardDescription className="text-base text-slate-500">
              Access the admin dashboard
            </CardDescription>
          </CardHeader>
          <CardContent>
            <div className="mb-4 p-3 bg-blue-50 border border-blue-200 rounded-lg">
